using System;using SourceContact;using LazySourceContact;using SourceResponse;
class ResponseTests {
 static int count;static void Check(bool ok,string name){count++;if(!ok)throw new Exception(name);}
 sealed class Oracle:ISourcePhaseOracle {public PhaseInterval Status;public ImpactAnatomy Anatomy;public int Calls;public PhaseInterval Inspect(double from,double to,out double first,out ImpactAnatomy anatomy){Calls++;first=from+(to-from)*.4;anatomy=Anatomy;return Status;}}
 static LazySurface Tetra(double scale=1,V offset=new V()){var p=new[]{new V(0,0,0)*scale+offset,new V(2,0,0)*scale+offset,new V(0,2,0)*scale+offset,new V(0,0,2)*scale+offset};var w=new double[16];for(int i=0;i<4;i++)w[i*4]=1;return new LazySurface(p,new[]{0,2,1,0,1,3,0,3,2,1,2,3},new int[16],w,new[]{new CompactNode{Count=4,VertexCount=4}},new[]{0,1,2,3},new[]{0,1,2,3},new[]{new NodeHull{Count=1,SumMin=1,SumMax=1}},new[]{new BoneHull{Bone=0,Min=new V(0,0,0)*scale+offset,Max=new V(2,2,2)*scale+offset}},1);}
 static void Main(){var sweep=new TranslationSweep(128);double t;V a=new V(0,0,0),b=new V(0,1,0),c=new V(0,0,1),d=new V(1,0,0),e=new V(1,1,0),f=new V(1,0,1);
 Check(sweep.Triangles(a,b,c,d,e,f,new V(2,0,0),out t)==SweepStatus.Contact&&Math.Abs(t-.5)<1e-10,"endpoint-clear crossing detected");
 Check(sweep.Triangles(a,b,c,d,e,f,new V(.5,0,0),out t)==SweepStatus.Clear,"short approach clear");
 Check(sweep.Triangles(a,b,c,d,e,f,new V(0,0,3),out t)==SweepStatus.Clear,"side miss");
 Check(sweep.Triangles(a,b,c,d,e,f,new V(-3,0,0),out t)==SweepStatus.Clear,"far retreat");
 Check(sweep.Triangles(a,b,c,new V(0,2,0),new V(0,3,0),new V(0,2,1),new V(0,3,0),out t)==SweepStatus.Contact&&Math.Abs(t-1.0/3)<1e-10,"coplanar sweep");
 Check(sweep.Triangles(a,a,c,d,e,f,new V(2,0,0),out t)==SweepStatus.Indeterminate,"degenerate conservative");
 // Exhaustive axis-aligned plane crossings: analytic TOI, with endpoint clear on both sides.
 for(int distance=1;distance<=12;distance++)for(int speed=1;speed<=15;speed++){var shift=new V(distance*.1,0,0);var status=sweep.Triangles(a,b,c,a+shift,b+shift,c+shift,new V(speed*.1,0,0),out t);Check(status==(speed>=distance?SweepStatus.Contact:SweepStatus.Clear),"analytic parity");if(speed>=distance)Check(Math.Abs(t-(double)distance/speed)<1e-10,"analytic time");}
 var oracle=new Oracle{Status=PhaseInterval.Contact,Anatomy=ImpactAnatomy.LegalHeadOrTorso};var attack=new AttackResponse(.1);var hit=attack.Tick(.3,.016,true,oracle);Check(hit.EmitImpact&&hit.BeginReaction&&hit.State==AttackState.Held&&Math.Abs(hit.Phase-.18)<1e-10,"source stop and reaction coincide");Check(!attack.Tick(.4,.016,true,oracle).EmitImpact,"single damage event");oracle.Status=PhaseInterval.ProvenClear;for(int i=0;i<30;i++)attack.Tick(.4,.016,true,oracle);Check(attack.State==AttackState.Finished&&attack.Phase==0,"smooth source return");
 attack=new AttackResponse(.1);oracle.Status=PhaseInterval.Contact;oracle.Anatomy=ImpactAnatomy.PassiveLimb;Check(!attack.Tick(.3,.016,true,oracle).EmitImpact&&attack.State==AttackState.Held,"passive obstruction no invented hit");
 attack=new AttackResponse(.1);oracle.Anatomy=ImpactAnatomy.LegalHeadOrTorso;Check(!attack.Tick(.3,.016,false,oracle).EmitImpact,"out of combat window no damage");
 attack=new AttackResponse(.1);oracle.Status=PhaseInterval.Indeterminate;var stop=attack.Tick(.3,.016,true,oracle);Check(stop.ConservativeStop&&attack.Phase==.1&&!stop.EmitImpact,"constant-root pose uncertainty stops");
 var identity=new double[16];identity[0]=identity[5]=identity[10]=identity[15]=1;var ma=Tetra(.1);var mb=Tetra(.1,new V(1,0,0));ma.SetPose(identity);mb.SetPose(identity);var resolver=new RootMotionResponse();var work=new WorkBudget(100000);var decision=resolver.Resolve(ma,mb,PairInspection.ProvisionalOutsideBoth,new V(2,0,0),new V(),ref work);Check(decision.Outcome==RootOutcome.StoppedBeforeContact&&decision.AcceptedFraction>.39&&decision.AcceptedFraction<.4,"root crossing bisection stops before actual surface");work=new WorkBudget(100000);Check(sweep.Query(ma,mb,decision.DeltaA,decision.DeltaB,ref work).Status==SweepStatus.Clear,"accepted whole prefix clear");work=new WorkBudget(0);Check(resolver.Resolve(ma,mb,PairInspection.ProvisionalOutsideBoth,new V(2,0,0),new V(),ref work).Outcome==RootOutcome.ConservativeStop,"root budget stop");work=new WorkBudget(100000);Check(resolver.Resolve(ma,mb,PairInspection.Contained,new V(2,0,0),new V(),ref work).Outcome==RootOutcome.InvalidStart,"nested start cannot authorize motion");
 Console.WriteLine("PASS response "+count+" assertions; temporal source oracle remains unimplemented");}
}
